class GlobalStateValue(typing.TypedDict):
    """Shape of global_state state key values"""
    admin: str
    registry: int
    totalVotes: int
    totalLists: int
    payoutGrace: int

class VoteFactoryState:
    """Methods to access state for the current VoteFactory app"""

